#!/usr/bin/env python3
from pwn import *
import time

def connect_to_server():
    return remote('rev.chal.csaw.io', 10010, level='debug')

def send_command(r, cmd):
    r.sendline(cmd.encode())
    try:
        return r.recvuntil(b'> ', timeout=2).decode()
    except EOFError:
        return "Connection closed"
    except Exception as e:
        return f"Error: {str(e)}"

def main():
    # Connect to server
    r = connect_to_server()

    try:
        # Wait for initial prompt
        initial = r.recvuntil(b'> ', timeout=2).decode()
        print("Initial prompt:", initial)

        # Send commands in sequence
        commands = ['start', 'balance']
        for cmd in commands:
            print(f"\nSending command: {cmd}")
            resp = send_command(r, cmd)
            print(f"Response: {resp}")
            time.sleep(1)

        # Do multiple pulls
        for i in range(5):
            print(f"\nPull attempt {i+1}")
            resp = send_command(r, 'pull')
            print(f"Pull result: {resp}")
            time.sleep(1)

            # Check balance after each pull
            resp = send_command(r, 'balance')
            print(f"Balance after pull: {resp}")
            time.sleep(1)

    except Exception as e:
        print(f"Error occurred: {str(e)}")
    finally:
        r.close()

if __name__ == '__main__':
    main()

