#!/usr/bin/env python3
from pwn import *
import time

# Configure logging
context.log_level = 'debug'

def connect_to_server():
    return remote('rev.chal.csaw.io', 10010)

def send_command(r, cmd):
    r.sendline(cmd.encode())
    time.sleep(0.5)
    return r.recvuntil(b'>', timeout=2).decode('utf-8', errors='ignore')

def analyze_pull_results(r):
    pulls = []
    balance = None

    try:
        # Start the game
        resp = send_command(r, 'start')
        log.info(f"Start response: {resp}")

        # Check balance
        resp = send_command(r, 'balance')
        log.info(f"Balance response: {resp}")
        if 'coins' in resp.lower():
            balance = int(''.join(filter(str.isdigit, resp)))

        # Do 10 pulls
        for i in range(10):
            resp = send_command(r, 'pull')
            log.info(f"Pull {i+1} response: {resp}")
            pulls.append(resp)
            time.sleep(1)

        return pulls, balance

    except Exception as e:
        log.error(f"Error during analysis: {e}")
        return pulls, balance

def main():
    try:
        r = connect_to_server()
        log.info("Connected to server")

        pulls, balance = analyze_pull_results(r)

        log.info(f"Initial balance: {balance}")
        log.info(f"Number of pulls recorded: {len(pulls)}")

        # Analyze patterns
        characters = []
        for pull in pulls:
            if 'got' in pull.lower():
                char = pull.split('got')[-1].strip()
                characters.append(char)

        log.info(f"Characters received: {characters}")

        r.close()

    except Exception as e:
        log.error(f"Error occurred: {e}")

if __name__ == '__main__':
    main()

